     [RelayCommand]
     private async Task RescanAsync()
     {
         if (IsScanning) return;

         IsScanning = true;
         ScanStatus = "Scanning…";
         AppLogger.Info("Dependency rescan requested by user.");

         // Mark all as scanning so the UI reflects progress immediately.
         foreach (var item in Dependencies)
             item.Status = DependencyStatus.Scanning;

         try
         {
             var allResultsTask = _checker.CheckAllAsync(l5xGitPath: L5xGitExePath);
