1. using System.Diagnostics;
2. using System.IO;
3. using System.Text.RegularExpressions;
4. using ABLogixGitManager.Models;
5. using Microsoft.Win32;
6. 
7. namespace ABLogixGitManager.Services;
8. 
9. /// <summary>
10. /// Non-destructive probes for the external dependencies required by this application.
11. /// Each probe is self-contained, async, and does not modify system state.
12. /// </summary>
13. public class DependencyCheckerService
14. {
15.     // -------------------------------------------------------------------------
16.     // Public probes
17.     // -------------------------------------------------------------------------
18. 
19.     /// <summary>
20.     /// Detects Git on the system PATH. Runs <c>git --version</c> and parses the result.
21.     /// Git is required for pull/restore operations.
22.     /// </summary>
23.     public async Task<DependencyInfo> CheckGitAsync(CancellationToken ct = default)
24.     {
25.         const string name = "Git for Windows";
26.         try
27.         {
28.             var (exitCode, output) = await RunProbeAsync("git", ["--version"], ct);
29. 
30.             if (exitCode == 0 && output.StartsWith("git version ", StringComparison.OrdinalIgnoreCase))
31.             {
32.                 var version = output["git version ".Length..].Trim();
33.                 return new DependencyInfo(name, DependencyStatus.Ready, version);
34.             }
35. 
36.             return new DependencyInfo(name, DependencyStatus.Missing,
37.                 Message: "git was not found on PATH. Install Git for Windows or add a compatible Git binary to your PATH.");
38.         }
39.         catch (Exception ex)
40.         {
41.             return new DependencyInfo(name, DependencyStatus.Failed,
42.                 Message: $"Detection failed: {ex.Message}");
43.         }
44.     }
45. 
46.     /// <summary>
47.     /// Detects the .NET SDK version from the system PATH. Runs <c>dotnet --version</c>.
48.     /// The SDK is only needed to compile VCS tools from source — not for ordinary use.
49.     /// </summary>
50.     public async Task<DependencyInfo> CheckDotNetSdkAsync(CancellationToken ct = default)
51.     {
52.         const string name = ".NET SDK 10";
53.         try
54.         {
55.             var (exitCode, output) = await RunProbeAsync("dotnet", ["--version"], ct);
56. 
57.             if (exitCode == 0)
58.             {
59.                 var version = output.Trim();
60.                 if (version.StartsWith("10.", StringComparison.Ordinal))
61.                     return new DependencyInfo(name, DependencyStatus.Ready, version,
62.                         Message: "Ready. Only required to compile VCS tools from source.");
63. 
64.                 return new DependencyInfo(name, DependencyStatus.Incompatible, version,
65.                     Message: $"Found .NET SDK {version}. SDK 10 is required if building VCS tools from source. Not needed for ordinary use.");
66.             }
67. 
68.             return new DependencyInfo(name, DependencyStatus.Missing,
69.                 Message: "The .NET SDK is not required for ordinary use. It is only needed to compile the VCS tools from source as a developer fallback.");
70.         }
71.         catch (Exception ex)
72.         {
73.             return new DependencyInfo(name, DependencyStatus.Failed,
74.                 Message: $"Detection failed: {ex.Message}");
75.         }
76.     }
77. 
78.     /// <summary>
79.     /// Checks whether the configured <c>l5xgit.exe</c> path exists and can be launched.
80.     /// l5xgit is required for both commit and restore operations.
81.     /// </summary>
82.     public async Task<DependencyInfo> CheckL5xGitAsync(string? configuredPath, CancellationToken ct = default)
83.     {
84.         const string name = "Rockwell VCS Tools (l5xgit)";
85. 
86.         if (string.IsNullOrWhiteSpace(configuredPath))
87.             return new DependencyInfo(name, DependencyStatus.Missing,
88.                 Message: "No path configured. Browse to l5xgit.exe in the toolbar or use Settings to configure it.");
89. 
90.         if (!File.Exists(configuredPath))
91.             return new DependencyInfo(name, DependencyStatus.Missing,
92.                 Message: $"Configured path not found: {configuredPath}");
93. 
94.         // Try a lightweight probe — l5xgit may exit nonzero for --help, but it should launch.
95.         try
96.         {
97.             var (_, output) = await RunProbeAsync(configuredPath, ["--help"], ct);
98.             var version = TryParseVersion(output);
99.             return new DependencyInfo(name, DependencyStatus.Ready, version,
100.                 Message: "Found at configured path.");
101.         }
102.         catch (Exception ex)
103.         {
104.             return new DependencyInfo(name, DependencyStatus.Failed,
105.                 Message: $"File found but could not be launched: {ex.Message}");
106.         }
107.     }
108. 
109.     /// <summary>
110.     /// Detects Studio 5000 / Logix Designer via Windows registry.
111.     /// Studio 5000 remains licensed vendor software; this application guides but does
112.     /// not attempt automated installation.
113.     /// </summary>
114.     public Task<DependencyInfo> CheckStudio5000Async(CancellationToken ct = default)
115.     {
116.         const string name = "Studio 5000 / Logix Designer";
117.         try
118.         {
119.             var version = DetectRegistryVersion(
120.             [
121.                 @"SOFTWARE\Rockwell Automation\RSLogix 5000",
122.                 @"SOFTWARE\WOW6432Node\Rockwell Automation\RSLogix 5000",
123.                 @"SOFTWARE\Rockwell Automation\Logix Designer",
124.                 @"SOFTWARE\WOW6432Node\Rockwell Automation\Logix Designer",
125.             ]);
126. 
127.             if (version is not null)
128.             {
129.                 var versionWarning = IsStudioVersionBelowMinimum(version)
130.                     ? $"Version {version} is below the minimum required V38. Upgrade to Studio 5000 V38 or newer for VCS tools to work."
131.                     : null;
132.                 return Task.FromResult(new DependencyInfo(
133.                     name,
134.                     versionWarning is null ? DependencyStatus.Ready : DependencyStatus.Incompatible,
135.                     version,
136.                     Message: versionWarning));
137.             }
138. 
139.             var uninstallDetection = DetectInstalledProductFromUninstall(
140.                 "Studio 5000",
141.                 "Logix Designer",
142.                 "RSLogix 5000");
143.             if (uninstallDetection.Version is not null)
144.             {
145.                 var versionWarning = IsStudioVersionBelowMinimum(uninstallDetection.Version)
146.                     ? $"Version {uninstallDetection.Version} is below the minimum required V38. Upgrade to Studio 5000 V38 or newer for VCS tools to work."
147.                     : null;
148.                 return Task.FromResult(new DependencyInfo(
149.                     name,
150.                     versionWarning is null ? DependencyStatus.Ready : DependencyStatus.Incompatible,
151.                     uninstallDetection.Version,
152.                     Message: versionWarning ?? $"Detected from installed programs as '{uninstallDetection.DisplayName}'."));
153.             }
154. 
155.             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Missing,
156.                 Message: "Not detected via registry. Install Studio 5000 / Logix Designer V38 or newer from your Rockwell Automation media or FactoryTalk Hub. V38+ is required by the VCS tools. Organizational IT deployment may be required."));
157.         }
158.         catch (Exception ex)
159.         {
160.             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Failed,
161.                 Message: $"Registry detection failed: {ex.Message}"));
162.         }
163.     }
164. 
165.     /// <summary>
166.     /// Detects the Logix Designer SDK via Windows registry.
167.     /// The SDK is typically installed alongside Studio 5000.
168.     /// </summary>
169.     public Task<DependencyInfo> CheckLogixDesignerSdkAsync(CancellationToken ct = default)
170.     {
171.         const string name = "Logix Designer SDK";
172.         try
173.         {
174.             var version = DetectRegistryVersion(
175.             [
176.                 @"SOFTWARE\Rockwell Automation\LogixDesignerSDK",
177.                 @"SOFTWARE\WOW6432Node\Rockwell Automation\LogixDesignerSDK",
178.                 @"SOFTWARE\Rockwell Automation\Logix Designer SDK",
179.                 @"SOFTWARE\WOW6432Node\Rockwell Automation\Logix Designer SDK",
180.             ]);
181. 
182.             if (version is not null)
183.                 return Task.FromResult(new DependencyInfo(name, DependencyStatus.Ready, version));
184. 
185.             var uninstallDetection = DetectInstalledProductFromUninstall(
186.                 "Logix Designer SDK",
187.                 "Studio 5000 SDK");
188.             if (uninstallDetection.Version is not null)
189.             {
190.                 return Task.FromResult(new DependencyInfo(
191.                     name,
192.                     DependencyStatus.Ready,
193.                     uninstallDetection.Version,
194.                     Message: $"Detected from installed programs as '{uninstallDetection.DisplayName}'."));
195.             }
196. 
197.             var sdkPackageFeedPath = GetRockwellSdkPackageFeedPath();
198.             if (Directory.Exists(sdkPackageFeedPath))
199.             {
200.                 return Task.FromResult(new DependencyInfo(
201.                     name,
202.                     DependencyStatus.Ready,
203.                     Message: $"Detected SDK package feed at '{sdkPackageFeedPath}'."));
204.             }
205. 
206.             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Missing,
207.                 Message: "Not detected via registry or installed-program metadata. The SDK is typically part of Studio 5000. Note: VCS source compile can still succeed when required packages are available from other package sources."));
208.         }
209.         catch (Exception ex)
210.         {
211.             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Failed,
212.                 Message: $"Registry detection failed: {ex.Message}"));
213.         }
214.     }
215. 
216.     /// <summary>
217.     /// Aggregates Studio 5000 and Logix Designer SDK into a single readiness row.
218.     /// </summary>
219.     public async Task<DependencyInfo> CheckStudioAndLogixSdkAsync(CancellationToken ct = default)
220.     {
221.         const string name = "Studio 5000 & Logix SDK";
222. 
223.         var studioTask = CheckStudio5000Async(ct);
224.         var sdkTask = CheckLogixDesignerSdkAsync(ct);
225.         await Task.WhenAll(studioTask, sdkTask);
226. 
227.         var studio = studioTask.Result;
228.         var sdk = sdkTask.Result;
229. 
230.         if (studio.Status == DependencyStatus.Failed || sdk.Status == DependencyStatus.Failed)
231.         {
232.             return new DependencyInfo(
233.                 name,
234.                 DependencyStatus.Failed,
235.                 Message: $"Studio: {studio.Message ?? studio.Status.ToString()}; SDK: {sdk.Message ?? sdk.Status.ToString()}");
236.         }
237. 
238.         if (studio.Status == DependencyStatus.Ready && sdk.Status == DependencyStatus.Ready)
239.         {
240.             var version = $"Studio={studio.Version ?? "unknown"}, SDK={sdk.Version ?? "unknown"}";
241.             return new DependencyInfo(name, DependencyStatus.Ready, version);
242.         }
243. 
244.         if (studio.Status == DependencyStatus.Missing && sdk.Status == DependencyStatus.Missing)
245.         {
246.             return new DependencyInfo(
247.                 name,
248.                 DependencyStatus.Missing,
249.                 Message: "Both Studio 5000 and Logix SDK are missing. These are required for ACD conversion during commit/restore, but not required to compile Rockwell VCS tools.");
250.         }
251. 
252.         return new DependencyInfo(
253.             name,
254.             DependencyStatus.Incompatible,
255.             Message: $"Partial detection — Studio: {studio.Status}, SDK: {sdk.Status}. Commit/restore needs both; VCS compile can proceed without them.");
256.     }
257. 
258.     /// <summary>
259.     /// Runs all probes concurrently and returns the results in a consistent order.
260.     /// </summary>
261.     public async Task<IReadOnlyList<DependencyInfo>> CheckAllAsync(
262.         string? l5xGitPath,
263.         CancellationToken ct = default)
264.     {
265.         AppLogger.Info("Dependency scan starting.");
266. 
267.         var studioAndSdkTask = CheckStudioAndLogixSdkAsync(ct);
268.         var dotNetTask = CheckDotNetSdkAsync(ct);
269.         var l5xGitTask = CheckL5xGitAsync(l5xGitPath, ct);
270.         var gitTask = CheckGitAsync(ct);
271. 
272.         await Task.WhenAll(studioAndSdkTask, dotNetTask, l5xGitTask, gitTask);
273. 
274.         IReadOnlyList<DependencyInfo> results =
275.         [
276.             studioAndSdkTask.Result,
277.             dotNetTask.Result,
278.             l5xGitTask.Result,
279.             gitTask.Result,
280.         ];
281. 
282.         foreach (var r in results)
283.             AppLogger.Info($"  [{r.Status,-12}] {r.Name} {r.Version ?? string.Empty}");
284. 
285.         var readyCount = results.Count(r => r.Status == DependencyStatus.Ready);
286.         AppLogger.Info($"Dependency scan complete — {readyCount}/{results.Count} ready.");
287. 
288.         return results;
289.     }
