291.     // -------------------------------------------------------------------------
292.     // Helpers
293.     // -------------------------------------------------------------------------
294. 
295.     private static string? DetectRegistryVersion(string[] keyPaths)
296.     {
297.         foreach (var path in keyPaths)
298.         {
299.             using var key = Registry.LocalMachine.OpenSubKey(path);
300.             if (key is null) continue;
301. 
302.             var version = key.GetValue("Version") as string
303.                 ?? key.GetValue("InstallVersion") as string;
304. 
305.             return version ?? "(version unknown)";
306.         }
307.         return null;
308.     }
309. 
310.     private static (string? DisplayName, string? Version) DetectInstalledProductFromUninstall(params string[] nameTokens)
311.     {
312.         var hives = new[] { RegistryHive.LocalMachine, RegistryHive.CurrentUser };
313.         var views = new[] { RegistryView.Registry64, RegistryView.Registry32 };
314.         const string uninstallPath = @"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall";
315. 
316.         foreach (var hive in hives)
317.         {
318.             foreach (var view in views)
319.             {
320.                 try
321.                 {
322.                     using var baseKey = RegistryKey.OpenBaseKey(hive, view);
323.                     using var uninstallKey = baseKey.OpenSubKey(uninstallPath);
324.                     if (uninstallKey is null)
325.                         continue;
326. 
327.                     foreach (var subKeyName in uninstallKey.GetSubKeyNames())
328.                     {
329.                         using var subKey = uninstallKey.OpenSubKey(subKeyName);
330.                         var displayName = subKey?.GetValue("DisplayName") as string;
331.                         if (string.IsNullOrWhiteSpace(displayName))
332.                             continue;
333. 
334.                         var matches = nameTokens.Any(token =>
335.                             displayName.Contains(token, StringComparison.OrdinalIgnoreCase));
