 using System.Diagnostics;
 using System.IO;
 using System.Text.RegularExpressions;
 using ABLogixGitManager.Models;
 using Microsoft.Win32;

 namespace ABLogixGitManager.Services;

 /// <summary>
 /// Non-destructive probes for the external dependencies required by this application.
 /// Each probe is self-contained, async, and does not modify system state.
 /// </summary>
 public class DependencyCheckerService
 {
     // -------------------------------------------------------------------------
     // Public probes
     // -------------------------------------------------------------------------

     /// <summary>
     /// Detects Git on the system PATH. Runs <c>git --version</c> and parses the result.
     /// Git is required for pull/restore operations.
     /// </summary>
     public async Task<DependencyInfo> CheckGitAsync(CancellationToken ct = default)
     {
         const string name = "Git for Windows";
         try
         {
             var (exitCode, output) = await RunProbeAsync("git", ["--version"], ct);

             if (exitCode == 0 && output.StartsWith("git version ", StringComparison.OrdinalIgnoreCase))
             {
                 var version = output["git version ".Length..].Trim();
                 return new DependencyInfo(name, DependencyStatus.Ready, version);
             }

             return new DependencyInfo(name, DependencyStatus.Missing,
                 Message: "git was not found on PATH. Install Git for Windows or add a compatible Git binary to your PATH.");
         }
         catch (Exception ex)
         {
             return new DependencyInfo(name, DependencyStatus.Failed,
                 Message: $"Detection failed: {ex.Message}");
         }
     }

     /// <summary>
     /// Detects the .NET SDK version from the system PATH. Runs <c>dotnet --version</c>.
     /// The SDK is only needed to compile VCS tools from source — not for ordinary use.
     /// </summary>
     public async Task<DependencyInfo> CheckDotNetSdkAsync(CancellationToken ct = default)
     {
         const string name = ".NET SDK 10";
         try
         {
             var (exitCode, output) = await RunProbeAsync("dotnet", ["--version"], ct);

             if (exitCode == 0)
             {
                 var version = output.Trim();
                 if (version.StartsWith("10.", StringComparison.Ordinal))
                     return new DependencyInfo(name, DependencyStatus.Ready, version,
                         Message: "Ready. Only required to compile VCS tools from source.");

                 return new DependencyInfo(name, DependencyStatus.Incompatible, version,
                     Message: $"Found .NET SDK {version}. SDK 10 is required if building VCS tools from source. Not needed for ordinary use.");
             }

             return new DependencyInfo(name, DependencyStatus.Missing,
                 Message: "The .NET SDK is not required for ordinary use. It is only needed to compile the VCS tools from source as a developer fallback.");
         }
         catch (Exception ex)
         {
             return new DependencyInfo(name, DependencyStatus.Failed,
                 Message: $"Detection failed: {ex.Message}");
         }
     }

     /// <summary>
     /// Checks whether the configured <c>l5xgit.exe</c> path exists and can be launched.
     /// l5xgit is required for both commit and restore operations.
     /// </summary>
     public async Task<DependencyInfo> CheckL5xGitAsync(string? configuredPath, CancellationToken ct = default)
     {
         const string name = "Rockwell VCS Tools (l5xgit)";

         if (string.IsNullOrWhiteSpace(configuredPath))
             return new DependencyInfo(name, DependencyStatus.Missing,
                 Message: "No path configured. Browse to l5xgit.exe in the toolbar or use Settings to configure it.");

         if (!File.Exists(configuredPath))
             return new DependencyInfo(name, DependencyStatus.Missing,
                 Message: $"Configured path not found: {configuredPath}");

         // Try a lightweight probe — l5xgit may exit nonzero for --help, but it should launch.
         try
         {
             var (_, output) = await RunProbeAsync(configuredPath, ["--help"], ct);
             var version = TryParseVersion(output);
             return new DependencyInfo(name, DependencyStatus.Ready, version,
                 Message: "Found at configured path.");
         }
         catch (Exception ex)
         {
             return new DependencyInfo(name, DependencyStatus.Failed,
                 Message: $"File found but could not be launched: {ex.Message}");
         }
     }

     /// <summary>
     /// Detects Studio 5000 / Logix Designer via Windows registry.
     /// Studio 5000 remains licensed vendor software; this application guides but does
     /// not attempt automated installation.
     /// </summary>
     public Task<DependencyInfo> CheckStudio5000Async(CancellationToken ct = default)
     {
         const string name = "Studio 5000 / Logix Designer";
         try
         {
             var version = DetectRegistryVersion(
             [
                 @"SOFTWARE\Rockwell Automation\RSLogix 5000",
                 @"SOFTWARE\WOW6432Node\Rockwell Automation\RSLogix 5000",
                 @"SOFTWARE\Rockwell Automation\Logix Designer",
                 @"SOFTWARE\WOW6432Node\Rockwell Automation\Logix Designer",
             ]);

             if (version is not null)
             {
                 var versionWarning = IsStudioVersionBelowMinimum(version)
                     ? $"Version {version} is below the minimum required V38. Upgrade to Studio 5000 V38 or newer for VCS tools to work."
                     : null;
                 return Task.FromResult(new DependencyInfo(
                     name,
                     versionWarning is null ? DependencyStatus.Ready : DependencyStatus.Incompatible,
                     version,
                     Message: versionWarning));
             }

             var uninstallDetection = DetectInstalledProductFromUninstall(
                 "Studio 5000",
                 "Logix Designer",
                 "RSLogix 5000");
             if (uninstallDetection.Version is not null)
             {
                 var versionWarning = IsStudioVersionBelowMinimum(uninstallDetection.Version)
                     ? $"Version {uninstallDetection.Version} is below the minimum required V38. Upgrade to Studio 5000 V38 or newer for VCS tools to work."
                     : null;
                 return Task.FromResult(new DependencyInfo(
                     name,
                     versionWarning is null ? DependencyStatus.Ready : DependencyStatus.Incompatible,
                     uninstallDetection.Version,
                     Message: versionWarning ?? $"Detected from installed programs as '{uninstallDetection.DisplayName}'."));
             }

             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Missing,
                 Message: "Not detected via registry. Install Studio 5000 / Logix Designer V38 or newer from your Rockwell Automation media or FactoryTalk Hub. V38+ is required by the VCS tools. Organizational IT deployment may be required."));
         }
         catch (Exception ex)
         {
             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Failed,
                 Message: $"Registry detection failed: {ex.Message}"));
         }
     }

     /// <summary>
     /// Detects the Logix Designer SDK via Windows registry.
     /// The SDK is typically installed alongside Studio 5000.
     /// </summary>
     public Task<DependencyInfo> CheckLogixDesignerSdkAsync(CancellationToken ct = default)
     {
         const string name = "Logix Designer SDK";
         try
         {
             var version = DetectRegistryVersion(
             [
                 @"SOFTWARE\Rockwell Automation\LogixDesignerSDK",
                 @"SOFTWARE\WOW6432Node\Rockwell Automation\LogixDesignerSDK",
                 @"SOFTWARE\Rockwell Automation\Logix Designer SDK",
                 @"SOFTWARE\WOW6432Node\Rockwell Automation\Logix Designer SDK",
             ]);

             if (version is not null)
                 return Task.FromResult(new DependencyInfo(name, DependencyStatus.Ready, version));

             var uninstallDetection = DetectInstalledProductFromUninstall(
                 "Logix Designer SDK",
                 "Studio 5000 SDK");
             if (uninstallDetection.Version is not null)
             {
                 return Task.FromResult(new DependencyInfo(
                     name,
                     DependencyStatus.Ready,
                     uninstallDetection.Version,
                     Message: $"Detected from installed programs as '{uninstallDetection.DisplayName}'."));
             }

             var sdkPackageFeedPath = GetRockwellSdkPackageFeedPath();
             if (Directory.Exists(sdkPackageFeedPath))
             {
                 return Task.FromResult(new DependencyInfo(
                     name,
                     DependencyStatus.Ready,
                     Message: $"Detected SDK package feed at '{sdkPackageFeedPath}'."));
             }

             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Missing,
                 Message: "Not detected via registry or installed-program metadata. The SDK is typically part of Studio 5000. Note: VCS source compile can still succeed when required packages are available from other package sources."));
         }
         catch (Exception ex)
         {
             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Failed,
                 Message: $"Registry detection failed: {ex.Message}"));
         }
     }

     /// <summary>
     /// Aggregates Studio 5000 and Logix Designer SDK into a single readiness row.
     /// </summary>
     public async Task<DependencyInfo> CheckStudioAndLogixSdkAsync(CancellationToken ct = default)
     {
         const string name = "Studio 5000 & Logix SDK";

         var studioTask = CheckStudio5000Async(ct);
         var sdkTask = CheckLogixDesignerSdkAsync(ct);
         await Task.WhenAll(studioTask, sdkTask);

         var studio = studioTask.Result;
         var sdk = sdkTask.Result;

         if (studio.Status == DependencyStatus.Failed || sdk.Status == DependencyStatus.Failed)
         {
             return new DependencyInfo(
                 name,
                 DependencyStatus.Failed,
                 Message: $"Studio: {studio.Message ?? studio.Status.ToString()}; SDK: {sdk.Message ?? sdk.Status.ToString()}");
         }

         if (studio.Status == DependencyStatus.Ready && sdk.Status == DependencyStatus.Ready)
         {
             var version = $"Studio={studio.Version ?? "unknown"}, SDK={sdk.Version ?? "unknown"}";
             return new DependencyInfo(name, DependencyStatus.Ready, version);
         }

         if (studio.Status == DependencyStatus.Missing && sdk.Status == DependencyStatus.Missing)
         {
             return new DependencyInfo(
                 name,
                 DependencyStatus.Missing,
                 Message: "Both Studio 5000 and Logix SDK are missing. These are required for ACD conversion during commit/restore, but not required to compile Rockwell VCS tools.");
         }

         return new DependencyInfo(
             name,
             DependencyStatus.Incompatible,
             Message: $"Partial detection — Studio: {studio.Status}, SDK: {sdk.Status}. Commit/restore needs both; VCS compile can proceed without them.");
     }

     /// <summary>
     /// Runs all probes concurrently and returns the results in a consistent order.
     /// </summary>
     public async Task<IReadOnlyList<DependencyInfo>> CheckAllAsync(
         string? l5xGitPath,
         CancellationToken ct = default)
     {
         AppLogger.Info("Dependency scan starting.");

         var studioAndSdkTask = CheckStudioAndLogixSdkAsync(ct);
         var dotNetTask = CheckDotNetSdkAsync(ct);
         var l5xGitTask = CheckL5xGitAsync(l5xGitPath, ct);
         var gitTask = CheckGitAsync(ct);

         await Task.WhenAll(studioAndSdkTask, dotNetTask, l5xGitTask, gitTask);

         IReadOnlyList<DependencyInfo> results =
         [
             studioAndSdkTask.Result,
             dotNetTask.Result,
             l5xGitTask.Result,
             gitTask.Result,
         ];

         foreach (var r in results)
             AppLogger.Info($"  [{r.Status,-12}] {r.Name} {r.Version ?? string.Empty}");

         var readyCount = results.Count(r => r.Status == DependencyStatus.Ready);
         AppLogger.Info($"Dependency scan complete — {readyCount}/{results.Count} ready.");

         return results;
     }

     // -------------------------------------------------------------------------
     // Helpers
     // -------------------------------------------------------------------------

     private static string? DetectRegistryVersion(string[] keyPaths)
     {
         foreach (var path in keyPaths)
         {
             using var key = Registry.LocalMachine.OpenSubKey(path);
             if (key is null) continue;

             var version = key.GetValue("Version") as string
                 ?? key.GetValue("InstallVersion") as string;

             return version ?? "(version unknown)";
         }
         return null;
     }

     private static (string? DisplayName, string? Version) DetectInstalledProductFromUninstall(params string[] nameTokens)
     {
         var hives = new[] { RegistryHive.LocalMachine, RegistryHive.CurrentUser };
         var views = new[] { RegistryView.Registry64, RegistryView.Registry32 };
         const string uninstallPath = @"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall";

         foreach (var hive in hives)
         {
             foreach (var view in views)
             {
                 try
                 {
                     using var baseKey = RegistryKey.OpenBaseKey(hive, view);
                     using var uninstallKey = baseKey.OpenSubKey(uninstallPath);
                     if (uninstallKey is null)
                         continue;

                     foreach (var subKeyName in uninstallKey.GetSubKeyNames())
                     {
                         using var subKey = uninstallKey.OpenSubKey(subKeyName);
                         var displayName = subKey?.GetValue("DisplayName") as string;
                         if (string.IsNullOrWhiteSpace(displayName))
                             continue;

                         var matches = nameTokens.Any(token =>
                             displayName.Contains(token, StringComparison.OrdinalIgnoreCase));
                         if (!matches)
                             continue;

                         var version =
                             subKey?.GetValue("DisplayVersion") as string ??
                             subKey?.GetValue("Version") as string ??
                             "(version unknown)";

                         return (displayName, version);
                     }
                 }
                 catch (Exception ex)
                 {
                     AppLogger.Warn($"Uninstall registry probe failed for {hive} {view}: {ex.Message}");
                 }
             }
         }

         return (null, null);
     }

     private static string GetRockwellSdkPackageFeedPath()
     {
         return Path.Combine(
             Environment.GetFolderPath(Environment.SpecialFolder.CommonDocuments),
             "Studio 5000",
             "Logix Designer SDK",
             "dotnet");
     }

     private static string? TryParseVersion(string output)
     {
         var match = Regex.Match(output, @"\d+\.\d+(?:\.\d+)?(?:\.\d+)?");
         return match.Success ? match.Value : null;
     }

     /// <summary>
     /// Returns <c>true</c> when the version string indicates a Studio 5000 release older than V38.
     /// The VCS tools require Logix Designer V38+ and SDK 2.2+.
     /// </summary>
     private static bool IsStudioVersionBelowMinimum(string version)
     {
         // Registry/uninstall versions are typically "38.00.00" or "36.00.00" style.
         // Extract the leading major number for comparison.
         var match = Regex.Match(version.Trim(), @"^(\d+)");
         if (match.Success && int.TryParse(match.Groups[1].Value, out var major))
             return major < 38;

         // Cannot parse — don't flag it as incompatible; let the user discover it at runtime.
         return false;
     }

     /// <summary>
     /// Launches an executable with a single argument list, captures combined output,
     /// and returns the exit code and stdout (falls back to stderr if stdout is empty).
     /// </summary>
     private static async Task<(int ExitCode, string Output)> RunProbeAsync(
         string exe,
         IEnumerable<string> args,
         CancellationToken ct)
     {
         var psi = new ProcessStartInfo(exe)
         {
             UseShellExecute = false,
             CreateNoWindow = true,
             RedirectStandardOutput = true,
             RedirectStandardError = true,
         };

         foreach (var arg in args)
             psi.ArgumentList.Add(arg);

         using var process = Process.Start(psi)
             ?? throw new InvalidOperationException($"Failed to start process: {exe}");

         var stdout = process.StandardOutput.ReadToEndAsync(ct);
         var stderr = process.StandardError.ReadToEndAsync(ct);

         await Task.WhenAll(stdout, stderr);
         await process.WaitForExitAsync(ct);

         var output = string.IsNullOrWhiteSpace(stdout.Result) ? stderr.Result : stdout.Result;
         return (process.ExitCode, output.Trim());
     }
 }

