1. using System.Diagnostics;
2. using System.IO;
3. using ABLogixGitManager.Models;
4. using ABLogixGitManager.Services;
5. 
6. namespace ABLogixGitManager.Tests;
7. 
8. /// <summary>
9. /// Regression coverage for the reported bug where Pull &amp; Restore aborted with
10. /// "There is no tracking information for the current branch" whenever the checked-out branch had
11. /// no configured upstream (e.g. right after <c>git init</c> + <c>git remote add</c>, or a locally
12. /// created branch that was never pushed with <c>--set-upstream</c>). These tests use a fake
13. /// "l5xgit.exe" (any real executable — only <c>File.Exists</c> is checked by validation) so the
14. /// git-pull retry logic can be exercised without requiring the actual licensed l5xgit/Logix
15. /// Designer SDK tool chain.
16. /// </summary>
17. public class L5xGitCliServicePullRetryTests
18. {
19.     private readonly L5xGitCliService _sut = new();
20. 
21.     // Stand-in for l5xgit.exe: validation only checks File.Exists, and the real restoreacd call
22.     // is expected to fail (or be unreachable) in these tests since it isn't a real l5xgit build.
23.     private static readonly string FakeL5xGitExePath = FindExecutableOnPath("git.exe") ?? "git.exe";
24. 
25.     private static string? FindExecutableOnPath(string exeName)
26.     {
27.         var pathEnv = Environment.GetEnvironmentVariable("PATH") ?? string.Empty;
28.         foreach (var dir in pathEnv.Split(Path.PathSeparator))
29.         {
30.             var candidate = Path.Combine(dir, exeName);
31.             if (File.Exists(candidate)) return candidate;
32.         }
33.         return null;
34.     }
35. 
36.     [Fact]
37.     public async Task PullAndRestoreAsync_SkipsGitPull_WhenNoRemoteConfigured()
38.     {
39.         using var repo = new TempGitRepo();
40.         repo.Commit("initial commit");
41.         var entry = new RepoEntry { Name = "test", GitRepoPath = repo.RepoPath, AcdFilePath = Path.Combine(repo.RepoPath, "does-not-exist.ACD") };
42.         var log = new List<string>();
43. 
44.         await _sut.PullAndRestoreAsync(entry, FakeL5xGitExePath, log.Add);
45. 
46.         Assert.Contains(log, l => l.Contains("No remote configured", StringComparison.OrdinalIgnoreCase));
47.         Assert.DoesNotContain(log, l => l.Contains("no tracking information", StringComparison.OrdinalIgnoreCase));
48.         Assert.DoesNotContain(log, l => l.Contains("abort", StringComparison.OrdinalIgnoreCase) && l.Contains("git pull", StringComparison.OrdinalIgnoreCase));
49.     }
50. 
51.     [Fact]
52.     public async Task PullAndRestoreAsync_RecoversFromMissingTrackingBranch_ViaExplicitPullRetry()
53.     {
54.         // Reproduces the exact reported scenario: a local branch pushed to a real remote without
55.         // ever configuring upstream tracking (plain `git push origin <branch>`, no `-u`), so a
56.         // bare `git pull` fails with "There is no tracking information for the current branch."
57.         // Left with no commits (an "unborn" branch) so the first push below is a clean fast-forward
58.         // instead of colliding with independent history on the same branch name.
59.         using var origin = new TempGitRepo(); // acts as the bare-equivalent "remote" for this test.
60.         // Allow pushing to the branch origin currently has checked out — a real bare repo doesn't
61.         // need this, but TempGitRepo always creates a normal (non-bare) working tree.
62.         origin.RunGit("config", "receive.denyCurrentBranch", "ignore");
63. 
64.         using var repo = new TempGitRepo();
65.         repo.Commit("local initial commit");
66.         repo.RunGit("remote", "add", "origin", origin.RepoPath);
67.         // Deliberately no --set-upstream / -u here — this is what reproduces the bug.
68.         repo.RunGit("push", "origin", "main");
69. 
70.         // Sanity check: confirm a plain `git pull` really does fail with the reported error before
71.         // asserting the app's fallback recovers from it.
72.         var plainPullExit = RunGitDirectly(repo.RepoPath, "pull");
73.         Assert.NotEqual(0, plainPullExit);
74. 
75.         var entry = new RepoEntry { Name = "test", GitRepoPath = repo.RepoPath, AcdFilePath = Path.Combine(repo.RepoPath, "does-not-exist.ACD") };
76.         var log = new List<string>();
77. 
78.         await _sut.PullAndRestoreAsync(entry, FakeL5xGitExePath, log.Add);
79. 
80.         Assert.Contains(log, l => l.Contains("retrying explicitly against", StringComparison.OrdinalIgnoreCase));
81.         Assert.DoesNotContain(log, l => l.Contains("git pull failed", StringComparison.OrdinalIgnoreCase));
82. 
83.         // Confirm the best-effort upstream fix-up also happened, so future plain pulls succeed.
84.         var trackingExit = RunGitDirectly(repo.RepoPath, "rev-parse", "--abbrev-ref", "main@{upstream}");
85.         Assert.Equal(0, trackingExit);
