 using System.Diagnostics;
 using System.IO;
 using ABLogixGitManager.Models;
 using ABLogixGitManager.Services;

 namespace ABLogixGitManager.Tests;

 /// <summary>
 /// Regression coverage for the reported bug where Pull &amp; Restore aborted with
 /// "There is no tracking information for the current branch" whenever the checked-out branch had
 /// no configured upstream (e.g. right after <c>git init</c> + <c>git remote add</c>, or a locally
 /// created branch that was never pushed with <c>--set-upstream</c>). These tests use a fake
 /// "l5xgit.exe" (any real executable — only <c>File.Exists</c> is checked by validation) so the
 /// git-pull retry logic can be exercised without requiring the actual licensed l5xgit/Logix
 /// Designer SDK tool chain.
 /// </summary>
 public class L5xGitCliServicePullRetryTests
 {
     private readonly L5xGitCliService _sut = new();

     // Stand-in for l5xgit.exe: validation only checks File.Exists, and the real restoreacd call
     // is expected to fail (or be unreachable) in these tests since it isn't a real l5xgit build.
     private static readonly string FakeL5xGitExePath = FindExecutableOnPath("git.exe") ?? "git.exe";

     private static string? FindExecutableOnPath(string exeName)
     {
         var pathEnv = Environment.GetEnvironmentVariable("PATH") ?? string.Empty;
         foreach (var dir in pathEnv.Split(Path.PathSeparator))
         {
             var candidate = Path.Combine(dir, exeName);
             if (File.Exists(candidate)) return candidate;
         }
         return null;
     }

     [Fact]
     public async Task PullAndRestoreAsync_SkipsGitPull_WhenNoRemoteConfigured()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");
         var entry = new RepoEntry { Name = "test", GitRepoPath = repo.RepoPath, AcdFilePath = Path.Combine(repo.RepoPath, "does-not-exist.ACD") };
         var log = new List<string>();

         await _sut.PullAndRestoreAsync(entry, FakeL5xGitExePath, log.Add);

         Assert.Contains(log, l => l.Contains("No remote configured", StringComparison.OrdinalIgnoreCase));
         Assert.DoesNotContain(log, l => l.Contains("no tracking information", StringComparison.OrdinalIgnoreCase));
         Assert.DoesNotContain(log, l => l.Contains("abort", StringComparison.OrdinalIgnoreCase) && l.Contains("git pull", StringComparison.OrdinalIgnoreCase));
     }

     [Fact]
     public async Task PullAndRestoreAsync_RecoversFromMissingTrackingBranch_ViaExplicitPullRetry()
     {
         // Reproduces the exact reported scenario: a local branch pushed to a real remote without
         // ever configuring upstream tracking (plain `git push origin <branch>`, no `-u`), so a
         // bare `git pull` fails with "There is no tracking information for the current branch."
         // Left with no commits (an "unborn" branch) so the first push below is a clean fast-forward
         // instead of colliding with independent history on the same branch name.
         using var origin = new TempGitRepo(); // acts as the bare-equivalent "remote" for this test.
         // Allow pushing to the branch origin currently has checked out — a real bare repo doesn't
         // need this, but TempGitRepo always creates a normal (non-bare) working tree.
         origin.RunGit("config", "receive.denyCurrentBranch", "ignore");

         using var repo = new TempGitRepo();
         repo.Commit("local initial commit");
         repo.RunGit("remote", "add", "origin", origin.RepoPath);
         // Deliberately no --set-upstream / -u here — this is what reproduces the bug.
         repo.RunGit("push", "origin", "main");

         // Sanity check: confirm a plain `git pull` really does fail with the reported error before
         // asserting the app's fallback recovers from it.
         var plainPullExit = RunGitDirectly(repo.RepoPath, "pull");
         Assert.NotEqual(0, plainPullExit);

         var entry = new RepoEntry { Name = "test", GitRepoPath = repo.RepoPath, AcdFilePath = Path.Combine(repo.RepoPath, "does-not-exist.ACD") };
         var log = new List<string>();

         await _sut.PullAndRestoreAsync(entry, FakeL5xGitExePath, log.Add);

         Assert.Contains(log, l => l.Contains("retrying explicitly against", StringComparison.OrdinalIgnoreCase));
         Assert.DoesNotContain(log, l => l.Contains("git pull failed", StringComparison.OrdinalIgnoreCase));

         // Confirm the best-effort upstream fix-up also happened, so future plain pulls succeed.
         var trackingExit = RunGitDirectly(repo.RepoPath, "rev-parse", "--abbrev-ref", "main@{upstream}");
         Assert.Equal(0, trackingExit);
     }

     private static int RunGitDirectly(string repoPath, params string[] args)
     {
         var psi = new ProcessStartInfo("git")
         {
             WorkingDirectory = repoPath,
             RedirectStandardOutput = true,
             RedirectStandardError = true,
             UseShellExecute = false,
             CreateNoWindow = true,
         };
         foreach (var arg in args) psi.ArgumentList.Add(arg);

         using var process = Process.Start(psi)!;
         process.StandardOutput.ReadToEnd();
         process.StandardError.ReadToEnd();
         process.WaitForExit();
         return process.ExitCode;
     }
 }

