     /// Detects the Logix Designer SDK via Windows registry.
     /// The SDK is typically installed alongside Studio 5000.
     /// </summary>
     public Task<DependencyInfo> CheckLogixDesignerSdkAsync(CancellationToken ct = default)
     {
         const string name = "Logix Designer SDK";
         try
         {
             var version = DetectRegistryVersion(
             [
                 @"SOFTWARE\Rockwell Automation\LogixDesignerSDK",
                 @"SOFTWARE\WOW6432Node\Rockwell Automation\LogixDesignerSDK",
                 @"SOFTWARE\Rockwell Automation\Logix Designer SDK",
                 @"SOFTWARE\WOW6432Node\Rockwell Automation\Logix Designer SDK",
             ]);

             if (version is not null)
                 return Task.FromResult(new DependencyInfo(name, DependencyStatus.Ready, version));

             var uninstallDetection = DetectInstalledProductFromUninstall(
                 "Logix Designer SDK",
                 "Studio 5000 SDK");
             if (uninstallDetection.Version is not null)
             {
                 return Task.FromResult(new DependencyInfo(
                     name,
                     DependencyStatus.Ready,
                     uninstallDetection.Version,
                     Message: $"Detected from installed programs as '{uninstallDetection.DisplayName}'."));
             }

             var sdkPackageFeedPath = GetRockwellSdkPackageFeedPath();
             if (Directory.Exists(sdkPackageFeedPath))
             {
                 return Task.FromResult(new DependencyInfo(
                     name,
                     DependencyStatus.Ready,
                     Message: $"Detected SDK package feed at '{sdkPackageFeedPath}'."));
             }

             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Missing,
                 Message: "Not detected via registry or installed-program metadata. The SDK is typically part of Studio 5000. Note: VCS source compile can still succeed when required packages are available from other package sources."));
         }
         catch (Exception ex)
         {
             return Task.FromResult(new DependencyInfo(name, DependencyStatus.Failed,
                 Message: $"Registry detection failed: {ex.Message}"));
         }
     }

